import{_ as r,o as a,c as d,a2 as l}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"共生劳动法","description":"","frontmatter":{},"headers":[],"relativePath":"constitution/41-共生劳动法.md","filePath":"constitution/41-共生劳动法.md"}'),o={name:"constitution/41-共生劳动法.md"};function i(e,t,n,s,h,c){return a(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="共生劳动法" tabindex="-1">共生劳动法 <a class="header-anchor" href="#共生劳动法" aria-label="Permalink to &quot;共生劳动法&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>41</td></tr><tr><td>所属模块</td><td>法律体系与治理框架</td></tr><tr><td>核心关键词</td><td>共生劳动、多劳多得、劳动权利、联产承包、反剥削</td></tr></tbody></table><h2 id="一、立法目的与基本原则" tabindex="-1">一、立法目的与基本原则 <a class="header-anchor" href="#一、立法目的与基本原则" aria-label="Permalink to &quot;一、立法目的与基本原则&quot;">​</a></h2><p>《共生劳动法》是锚点共生文明法律体系中与《共生宪法》并列的核心法律之一，旨在规范衡元宙内一切劳动与贡献行为，确立&quot;多劳多得、自生自长&quot;的分配秩序，从法律层面根除掠夺式剥削的土壤。</p><p>本法确立以下基本原则：</p><table tabindex="0"><thead><tr><th>原则</th><th>内涵</th></tr></thead><tbody><tr><td>劳动尊严原则</td><td>一切合法劳动均受法律保护，劳动者人格尊严不受侵犯</td></tr><tr><td>多劳多得原则</td><td>劳动报酬与贡献量直接挂钩，贡献越大收益越高，禁止不劳而获</td></tr><tr><td>自愿劳动原则</td><td>禁止强制劳动与奴役，劳动者有权自由选择劳动内容与劳动方式</td></tr><tr><td>公平报酬原则</td><td>同工同酬，禁止基于种族、修为、出身的报酬歧视</td></tr><tr><td>劳动保障原则</td><td>国家与文明有义务为劳动者提供安全的劳动环境与基本社会保障</td></tr><tr><td>共生协作原则</td><td>鼓励劳动者之间的协作与互助，反对恶性竞争与零和博弈</td></tr></tbody></table><h2 id="二、劳动者基本权利" tabindex="-1">二、劳动者基本权利 <a class="header-anchor" href="#二、劳动者基本权利" aria-label="Permalink to &quot;二、劳动者基本权利&quot;">​</a></h2><p>共生劳动法赋予衡元宙内一切具备劳动能力的生命以下权利：</p><ol><li><strong>平等就业权</strong>：任何生命在求职与就业过程中不受种族、修为、出身、性别等因素的歧视。</li><li><strong>自由择业权</strong>：劳动者有权根据自身意愿与能力选择职业、岗位与工作地点，有权依法变更职业。</li><li><strong>合理报酬权</strong>：劳动者有权获得与其劳动贡献相匹配的报酬，报酬不得低于文明规定的最低保障标准。</li><li><strong>休息休假权</strong>：劳动者有权获得合理的工作时间安排与定期休假，禁止无限制延长劳动时间。</li><li><strong>劳动安全权</strong>：劳动者有权在安全、卫生的环境中劳动，用人单位必须提供符合标准的劳动保护条件。</li><li><strong>职业培训权</strong>：劳动者有权获得职业技能培训与修炼指导，用人单位与国家有义务提供培训资源。</li><li><strong>结社与协商权</strong>：劳动者有权依法组织或加入劳动者协会，有权通过集体协商维护自身权益。</li><li><strong>申诉救济权</strong>：劳动者在劳动权益受到侵害时，有权向劳动仲裁机构与共生法院提起申诉与诉讼。</li></ol><h2 id="三、联产承包机制的法律化" tabindex="-1">三、联产承包机制的法律化 <a class="header-anchor" href="#三、联产承包机制的法律化" aria-label="Permalink to &quot;三、联产承包机制的法律化&quot;">​</a></h2><p>联产承包机制是锚点共生文明资源分配的核心制度，《共生劳动法》将其以法律形式固定下来：</p><ul><li><strong>承包主体</strong>：任何具备劳动能力的生命均可作为承包主体，个人或集体均可承包。</li><li><strong>承包内容</strong>：包括但不限于修炼资源开发、位面维护、知识传承、技术研发、公共服务等领域。</li><li><strong>承包期限</strong>：根据承包内容的性质确定，短期承包为一至三年，长期承包为五至二十年，到期可续包。</li><li><strong>收益分配</strong>：承包者的收益与其产出直接挂钩，产出的一部分上缴公共积累，剩余部分归承包者所有。</li><li><strong>退出机制</strong>：承包者有权在合理期限内提前通知后退出承包，不得被强制束缚于承包关系。</li><li><strong>纠纷解决</strong>：承包纠纷优先通过劳动仲裁解决，对仲裁结果不服的可向共生法院起诉。</li></ul><h2 id="四、特殊劳动保护" tabindex="-1">四、特殊劳动保护 <a class="header-anchor" href="#四、特殊劳动保护" aria-label="Permalink to &quot;四、特殊劳动保护&quot;">​</a></h2><p>针对衡元宙内不同生命形态的特殊需求，本法设立特殊劳动保护制度：</p><table tabindex="0"><thead><tr><th>保护对象</th><th>特殊保护措施</th></tr></thead><tbody><tr><td>初级修炼者</td><td>不得安排超出其能力范围的高危劳动，须配备导师指导</td></tr><tr><td>孕产期女性生命</td><td>享有不少于六个月的带薪产假，哺乳期内不得安排高强度劳动</td></tr><tr><td>残疾与伤病生命</td><td>享有合理的劳动岗位调整与无障碍劳动环境保障</td></tr><tr><td>异族劳动者</td><td>用人单位须尊重异族的生理特性与文化习惯，提供适配的劳动条件</td></tr><tr><td>高龄劳动者</td><td>达到一定年龄后可申请减轻劳动强度或转为顾问性岗位</td></tr></tbody></table><h2 id="五、法律责任与实施保障" tabindex="-1">五、法律责任与实施保障 <a class="header-anchor" href="#五、法律责任与实施保障" aria-label="Permalink to &quot;五、法律责任与实施保障&quot;">​</a></h2><p>用人单位违反本法规定的，视情节轻重承担以下责任：</p><ol><li>支付劳动者应得报酬及赔偿金（赔偿金为欠付报酬的一至三倍）。</li><li>被责令限期整改，逾期不改的处以罚款。</li><li>情节严重的，吊销经营许可并禁止相关责任人在一定期限内从事管理工作。</li><li>构成犯罪的，依法追究刑事责任。</li></ol><p>国家设立劳动监察机构，负责对用人单位遵守劳动法的情况进行监督检查。劳动者协会有权代表劳动者参与劳动监察与集体协商。</p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>《共生劳动法》是锚点共生文明&quot;多劳多得&quot;理念的法律载体。它将劳动从被剥削的对象转变为受尊重的权利，将分配从掠夺式占有转变为贡献式回报，为万族共进奠定了坚实的劳动制度基础。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>40-共生宪法总纲</li><li>06-多劳多得分配原理</li><li>22-资源分配联产承包机制</li><li>42-消费者保护法</li></ul>',23)])])}const g=r(o,[["render",i]]);export{b as __pageData,g as default};
